//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_PREFLIGHT_CALIBRATION_ACCELEROMETER(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.PREFLIGHT_CALIBRATION_ACCELEROMETER
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.PREFLIGHT_CALIBRATION_ACCELEROMETER_NONE.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.PREFLIGHT_CALIBRATION_ACCELEROMETER
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.PREFLIGHT_CALIBRATION_ACCELEROMETER_NONE, dec)
	})
}
